$checks=0;$assert=function(bool $ok,string $why)use(&$checks){if(!$ok)throw new RuntimeException($why);$checks++;};
$deny=function(callable $call,string $code)use($assert){try{$call();}catch(ApiException $e){$assert($e->errorCode===$code,'Expected '.$code.', got '.$e->errorCode);return;}throw new RuntimeException('Expected '.$code);};
$service=new PractitionerEnquiryService($database);$sequence=0;
$make=function(string $email='applicant@example.test')use(&$sequence):array{return ['idempotency_key'=>'10000000-0000-4000-8000-'.str_pad(dechex(++$sequence),12,'0',STR_PAD_LEFT),'full_name'=>'Synthetic Applicant','email'=>$email,'phone'=>'','discipline'=>'Massage therapy','credentials'=>'Synthetic only','service_area'=>'Toronto, Ontario','message'=>'Synthetic practice introduction','consent'=>true,'website'=>''];};
$body=$make();$result=$service->submit(1,$body,'127.0.0.1');
$assert($result===['received'=>true,'reference'=>$body['idempotency_key']],'Public response contains only acknowledgement and reference');
$assert($service->submit(1,$body,'127.0.0.1')===$result,'Retry returns same receipt');
$assert((int)$pdo->query('SELECT COUNT(*) FROM practitioner_enquiries')->fetchColumn()===1,'Retry creates no duplicate');
$deny(fn()=>$service->submit(1,array_replace($body,['message'=>'Different']),'127.0.0.1'),'idempotency_conflict');
