$deny(fn()=>$service->submit(999,$make(),'127.0.0.1'),'clinic_not_found');
$admin=new AuthContext(1,1,'','','','staff',['clinic_admin']);$foreign=new AuthContext(30,2,'','','','staff',['super_admin']);
$list=$service->list($admin,1);$id=(int)$list['items'][0]['id'];
$assert($list['settings']['recipient_email']==='info@copihue.ca','Migration seeds only the Wellnexa host recipient');
$assert($service->list($platform,2)['items']===[],'Central administration selects a clinic explicitly');
$assert($service->list($platform,2)['settings']['enabled']===false,'Unconfigured clinics do not accept enquiries by default');
$deny(fn()=>$service->submit(2,$make('other-clinic@example.test'),'127.0.0.1'),'enquiries_closed');
$deny(fn()=>$service->list($foreign,1),'forbidden');
$deny(fn()=>$service->list($clinician,1),'forbidden');
$deny(fn()=>$service->list($admin,1,['page'=>0]),'validation_error');
$assert($service->update($admin,1,$id,['status'=>'contacted','revision'=>1],'test')['revision']===2,'Clinic admin marks contacted');
$deny(fn()=>$service->update($admin,1,$id,['status'=>'closed','revision'=>1],'test'),'enquiry_changed');
$deny(fn()=>$service->update($foreign,2,$id,['status'=>'closed','revision'=>2],'test'),'enquiry_not_found');
$settings=$service->saveSettings($platform,1,['recipient_email'=>'future@example.test','enabled'=>true,'revision'=>1],'test');
$assert($settings['recipient_email']==='future@example.test'&&$settings['revision']===2,'Application admin updates notification recipient');
$deny(fn()=>$service->saveSettings($platform,1,['recipient_email'=>'stale@example.test','enabled'=>true,'revision'=>1],'test'),'settings_changed');
$deny(fn()=>$service->saveSettings($platform,1,['recipient_email'=>'bad','enabled'=>true,'revision'=>2],'test'),'validation_error');
$_ENV['MAIL_ENABLED']='false';
$assert($service->notify(1,$id)['notification_status']==='disabled','Disabled email never loses saved enquiry');
$_ENV['MAIL_ENABLED']='true';$sent=[];
$assert($service->notify(1,$id,function(...$args)use(&$sent){$sent[]=$args;})['notification_status']==='sent','Notification can send from saved inbox');
$assert(count($sent)===1&&$sent[0][0]==='future@example.test'&&!str_contains($sent[0][2],$body['email']),'Mail uses updated recipient without applicant details');
$service->notify(1,$id,function(...$args)use(&$sent){$sent[]=$args;});
$assert(count($sent)===1,'Sent mail is not automatically resent');
$body2=$make('second@example.test');$service->submit(1,$body2,'127.0.0.1');$id2=(int)$pdo->lastInsertId();
$q=$pdo->prepare('SELECT id FROM practitioner_enquiries WHERE reference=?');$q->execute([$body2['idempotency_key']]);$id2=(int)$q->fetchColumn();
$assert($service->notify(1,$id2,fn()=>throw new MailSendException('Synthetic refusal',true))['notification_status']==='failed','Mail failure is recorded separately from receipt');
$assert($service->notify(1,$id2,fn()=>throw new MailSendException('Unknown outcome',true,true))['notification_status']==='needs_review','Ambiguous mail is not automatically retried');
$assert($service->notify(1,$id2,fn()=>throw new RuntimeException('Must not send'))['notification_status']==='unchanged','Unknown outcome requires review');
