$deny(fn()=>$service->submit(1,$make($body['email']),'127.0.0.1'),'rate_limited');
$assert($service->submit(1,$body,'127.0.0.1')===$result,'Idempotent retry works after rate limit');
$settings=$service->saveSettings($platform,1,['recipient_email'=>'future@example.test','enabled'=>false,'revision'=>2],'test');
$deny(fn()=>$service->submit(1,$make('closed@example.test'),'127.0.0.1'),'enquiries_closed');
